// The ref closes the gap before React renders the disabled buttons after an activation.
function useAdminActionLock(): {
    isPending: (key: string) => boolean;
    begin: (key: string) => boolean;
    end: (key: string) => void;
} {
    const pendingRef = useRef(new Set<string>());
    const [pending, setPending] = useState<Set<string>>(new Set());
    const begin = useCallback((key: string): boolean => {
        if (pendingRef.current.has(key)) return false;
        pendingRef.current.add(key);
        setPending(new Set(pendingRef.current));
        return true;
    }, []);
    const end = useCallback((key: string): void => {
        pendingRef.current.delete(key);
        setPending(new Set(pendingRef.current));
    }, []);
    return { isPending: (key) => pending.has(key), begin, end };
}

